UIWelderSparkEmitter=function(game){Phaser.Particles.Arcade.Emitter.call(this,game,0,0,100);this.particleClass=UIWelderSparkParticle;this.makeParticles();this.minParticleSpeed.setTo(UIConstants.WELDER_SPARK_MIN_X_SPEED,UIConstants.WELDER_SPARK_MIN_Y_SPEED);this.maxParticleSpeed.setTo(UIConstants.WELDER_SPARK_MAX_X_SPEED,UIConstants.WELDER_SPARK_MAX_Y_SPEED);this.setAlpha(0.5,1.0);this.setRotation(0,0);this.minParticleScale=0.7;this.maxParticleScale=1.0;this.gravity=500;this.emitterPointsOld=null;this.emitterPointsNew=null;this.floor=null;this.kill();this.visible=false;};UIWelderSparkEmitter.prototype=Object.create(Phaser.Particles.Arcade.Emitter.prototype);UIWelderSparkEmitter.prototype.constructor=UIWelderSparkEmitter;UIWelderSparkEmitter.prototype.update=function(){if(!this.exists){return;}Phaser.Particles.Arcade.Emitter.prototype.update.call(this);this.game.physics.arcade.collide(this,this.floor);if(this.countLiving()==0){this.kill();this.visible=false;}};UIWelderSparkEmitter.prototype.postUpdate=function(){if(!this.exists){return;}Phaser.Particles.Arcade.Emitter.prototype.postUpdate.call(this);};UIWelderSparkEmitter.prototype.spawn=function(tankIcon,floor,emitterPointsOld,emitterPointsNew){this.revive();this.visible=true;this.floor=floor;this.emitterPointsOld=emitterPointsOld;this.emitterPointsNew=emitterPointsNew;UIWelderSparkParticle.setSpawnPoints(tankIcon,this.emitterPointsOld,this.emitterPointsNew);this.flow(UIConstants.GARAGE_WELD_PARTICLE_TIME,16,1,UIConstants.GARAGE_WELD_SPARK_TIME/16*1);};UIWelderSparkEmitter.prototype.remove=function(){this.on=false;};UIWelderSparkEmitter.prototype.retire=function(){this.kill();this.visible=false;this.callAll('retire');};